// One item per image URL, duplicates removed.
const found = $input.first().json.images || []
const urls = [...new Set(found.map(img => img.url || img.src || img).filter(u => typeof u === 'string' && u.startsWith('http')))]
if (!urls.length) throw new Error('No images found on this page. Check the URL in Fetch Images from MiroMiro.')
return urls.map(url => ({ json: { url }, pairedItem: { item: 0 } }))

// Put every downloaded image on one item so they land in one zip.
const binary = {}
$input.all().forEach((item, i) => { if (item.binary?.data) binary['image_' + String(i + 1).padStart(2, '0')] = item.binary.data })
return [{ json: { images: Object.keys(binary).length }, binary, pairedItem: { item: 0 } }]

// The first result lists every other section on the page, with a ready selector.
const first = $input.first().json
return (first.sections || []).filter(s => s.selector !== first.selector)
  .sort((a, b) => a.order - b.order).slice(0, 12)
  .map(s => ({ json: { url: first.url || 'https://linear.app', selector: s.selector, section: s.label }, pairedItem: { item: 0 } }))

// Each section files itself under the page; the newest link has them all.
const all = [...$('Extract Hero and Find Sections').all(), ...$input.all()].map(i => i.json)
const page = all.filter(r => r.pagePreviewUrl).pop()?.pagePreviewUrl
return [{ json: { pagePreviewUrl: page, sections: all.filter(r => r.code).length }, pairedItem: { item: 0 } }]
